// Evaluate the exact low-period admission rule for the archival omission cover.
const fixedSpecials = {
  2: [11,13,33,17,25,39],
  4: [11,13,20,33,22,17],
};
const primes=[2,3,5,7,11,13];
function valuation(n,p){
  let index=0;
  while(n%p===0){n/=p;index++;}
  return index;
}
const summaries=[];
for(const [step,parity] of [[2,0],[4,0],[4,1]]){
  const usable=extras.filter(([a,d])=>step===2||d%2||a%2===parity);
  for(let mask=0;mask<2**usable.length;mask++){
    const selected=usable.filter((_,i)=>mask&(1<<i));
    const L=selected.reduce((l,[,d])=>lcm(l,d/gcd(d,step/2)),105);
    const blocked=[];
    for(const g of divisors(L))for(let m=1;m<=30;m++){
      const h=g*m;
      if(gcd(h,L)!==g)continue;
      if(fixedSpecials[step].includes(h)||!hasFree(h,step))blocked.push([h,m]);
    }
    const thresholds=primes.map(p=>2+Math.max(-1,...blocked.map(([,m])=>valuation(m,p))));
    summaries.push({step,parity,selected:selected.map(x=>x[2]),L,thresholds,
                    witnesses:primes.map((p,i)=>blocked.filter(([,m])=>valuation(m,p)===thresholds[i]-2))});
  }
}
console.log(JSON.stringify(summaries));

