"""Check bounds for periods that cannot be descended in the omission model."""
from itertools import product
from math import gcd, prod
from pathlib import Path
import json

PRIMES = (2, 3, 5, 7, 11, 13)
SCOPES = ((2, 0), (4, 0), (4, 1))
INVENTORY = json.loads(Path(__file__).with_name('inventory.json').read_text())


def periods(exclusive_limits):
    for exponents in product(*map(range, exclusive_limits)):
        m = prod(p**e for p, e in zip(PRIMES, exponents))
        weight = sum(e*(p-1) for p, e in zip(PRIMES, exponents))
        yield m, weight


def first_descent_ceiling(step, parity):
    largest = 0
    for row in INVENTORY:
        if (row['step'], row['parity']) != (step, parity):
            continue
        offset = 1+len(row['selected'])+(step == 4)
        for m, weight in periods(row['thresholds']):
            quotient = (step*row['L']*m-1)//5040
            max_budget = 10+quotient.bit_length()
            if quotient and max_budget >= max(11, weight+offset):
                largest = max(largest, max_budget)
    return largest


def terminal_period_counts(step, parity, budget):
    cutoff = 5040*2**(budget-11)
    representatives = full_periods = 0
    for row in INVENTORY:
        if (row['step'], row['parity']) != (step, parity):
            continue
        L = row['L']
        offset = 1+len(row['selected'])+(step == 4)
        divisors = [g for g in range(1,L+1) if L%g == 0]
        limits = [
            min(upper, 1 + (budget-offset)//(p-1))
            if budget-(p-1) >= 20 else 1 + (budget-offset)//(p-1)
            for p, upper in zip(PRIMES, row['thresholds'])
        ]
        for m, weight in periods(limits):
            if weight+offset > budget or step*L*m <= cutoff:
                continue
            count = sum(
                step*g*m > cutoff and gcd(g*m, L) == g for g in divisors
            )
            if count:
                representatives += 1
                full_periods += count
    return [representatives, full_periods]


if __name__ == '__main__':
    print(json.dumps({
        'ceilings': [first_descent_ceiling(s,p) for s,p in SCOPES],
        'terminal_counts': {
            b: [terminal_period_counts(s,p,b) for s,p in SCOPES]
            for b in (22,23,24,25)
        },
    }, separators=(',', ':')))
